+@page "/board"
+@using sv_b2889fdb60df4017a2a8818e85f3de80.Services
+@inject ITaskService TaskService
+@rendermode InteractiveServer
+
+<PageTitle>Kanban Board</PageTitle>
+
+<h2 class="mb-3">Project Board</h2>
+
+@if (_loading)
+{
+    <div class="d-flex justify-content-center my-5">
+        <div class="spinner-border" role="status">
+            <span class="visually-hidden">Loading...</span>
+        </div>
+    </div>
+}
+else if (_error is not null)
+{
+    <div class="alert alert-danger" role="alert">
+        <strong>Error:</strong> @_error
+        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasksAsync">Retry</button>
+    </div>
+}
+else
+{
+    @* Summary stats bar *@
+    <div class="row g-2 mb-3">
+        <div class="col">
+            <div class="card text-center">
+                <div class="card-body py-2">
+                    <div class="fw-bold">Total</div>
+                    <div class="fs-5">@_allTasks.Count</div>
+                </div>
+            </div>
+        </div>
+        @foreach (var col in Columns)
+        {
+            <div class="col">
+                <div class="card text-center">
+                    <div class="card-body py-2">
+                        <div class="fw-bold">@col</div>
+                        <div class="fs-5">@GetTasksForColumn(col).Count</div>
+                    </div>
+                </div>
+            </div>
+        }
+        <div class="col">
+            <div class="card text-center border-danger">
+                <div class="card-body py-2">
+                    <div class="fw-bold text-danger">Overdue</div>
+                    <div class="fs-5 text-danger">@_allTasks.Count(t => t.DueDate < DateTime.Today)</div>
+                </div>
+            </div>
+        </div>
+    </div>
+
+    @* Search bar *@
+    <div class="mb-3">
+        <input type="text" class="form-control" placeholder="Search tasks by title..."
+               @bind="_searchTerm" @bind:event="oninput" />
+    </div>
+
+    @* Kanban columns *@
+    <div class="row g-3">
+        @for (int i = 0; i < Columns.Length; i++)
+        {
+            var colIndex = i;
+            var column = Columns[colIndex];
+            var tasks = GetFilteredTasksForColumn(column);
+
+            <div class="col-md-4">
+                <div class="card h-100">
+                    <div class="card-header d-flex justify-content-between align-items-center">
+                        <span class="fw-bold">@column</span>
+                        <span class="badge bg-secondary">@GetTasksForColumn(column).Count</span>
+                    </div>
+                    <div class="card-body d-flex flex-column gap-2 overflow-auto" style="min-height: 200px;">
+                        @foreach (var task in tasks)
+                        {
+                            <div class="card shadow-sm">
+                                <div class="card-body p-2">
+                                    <div class="fw-semibold mb-1">@task.Title</div>
+                                    <div class="d-flex justify-content-between align-items-center mb-1">
+                                        <small class="text-muted">@task.Assignee</small>
+                                        <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
+                                    </div>
+                                    <div class="d-flex justify-content-between align-items-center">
+                                        <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
+                                        <div>
+                                            @if (colIndex > 0)
+                                            {
+                                                <button class="btn btn-sm btn-outline-secondary me-1"
+                                                        @onclick="() => MoveTaskAsync(task.Id, Columns[colIndex - 1])"
+                                                        disabled="@_moving">
+                                                    &larr; Move Left
+                                                </button>
+                                            }
+                                            @if (colIndex < Columns.Length - 1)
+                                            {
+                                                <button class="btn btn-sm btn-outline-secondary"
+                                                        @onclick="() => MoveTaskAsync(task.Id, Columns[colIndex + 1])"
+                                                        disabled="@_moving">
+                                                    Move Right &rarr;
+                                                </button>
+                                            }
+                                        </div>
+                                    </div>
+                                </div>
+                            </div>
+                        }
+
+                        @if (_addingToColumn == column)
+                        {
+                            <div class="card border-primary">
+                                <div class="card-body p-2">
+                                    <div class="mb-2">
+                                        <input type="text" class="form-control form-control-sm" placeholder="Title"
+                                               @bind="_newTitle" />
+                                    </div>
+                                    <div class="mb-2">
+                                        <input type="text" class="form-control form-control-sm" placeholder="Assignee"
+                                               @bind="_newAssignee" />
+                                    </div>
+                                    <div class="mb-2">
+                                        <select class="form-select form-select-sm" @bind="_newPriority">
+                                            <option value="High">High</option>
+                                            <option value="Medium">Medium</option>
+                                            <option value="Low">Low</option>
+                                        </select>
+                                    </div>
+                                    <div class="mb-2">
+                                        <input type="date" class="form-control form-control-sm"
+                                               @bind="_newDueDate" />
+                                    </div>
+                                    <div class="d-flex gap-2">
+                                        <button class="btn btn-sm btn-primary" @onclick="SaveNewTaskAsync"
+                                                disabled="@_saving">
+                                            @(_saving ? "Saving..." : "Save")
+                                        </button>
+                                        <button class="btn btn-sm btn-outline-secondary" @onclick="CancelAdd"
+                                                disabled="@_saving">
+                                            Cancel
+                                        </button>
+                                    </div>
+                                </div>
+                            </div>
+                        }
+                    </div>
+                    <div class="card-footer">
+                        <button class="btn btn-sm btn-outline-primary w-100"
+                                @onclick="() => StartAdd(column)"
+                                disabled="@(_addingToColumn is not null)">
+                            + Add Task
+                        </button>
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private static readonly string[] Columns = ["To Do", "In Progress", "Done"];
+
+    private List<TaskItem> _allTasks = new();
